import{_ as i,a0 as o,w as s,s as d,I as t,x as e,a1 as l,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"什么是防火墙？ | LCTT x X-CMD","titleTemplate":false,"description":"什么是防火墙？ | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什么是防火墙？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什么是防火墙？ | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171011 What is a firewall","title":"什么是防火墙？","tag":"201801","desc":""},"relativePath":"201801/20171011 What is a firewall.md","filePath":"[post].md"}'),h={name:"201801/20171011 What is a firewall.md"};function f(m,a,w,b,u,P){const r=o("Link");return s(),d("div",null,[a[15]||(a[15]=t("h1",{id:"什么是防火墙",tabindex:"-1"},[e("什么是防火墙？ "),t("a",{class:"header-anchor",href:"#什么是防火墙","aria-label":"Permalink to “什么是防火墙？”"},"​")],-1)),a[16]||(a[16]=t("blockquote",null,[t("p",null,"流行的防火墙是多数组织主要的边界防御。")],-1)),a[17]||(a[17]=t("p",null,[t("img",{src:"https://images.techhive.com/images/article/2017/04/firewall-100716789-large.jpg",alt:""})],-1)),a[18]||(a[18]=t("p",null,"基于网络的防火墙已经在美国企业无处不在，因为它们证实了抵御日益增长的威胁的防御能力。",-1)),a[19]||(a[19]=t("p",null,"通过网络测试公司 NSS 实验室最近的一项研究发现，高达 80% 的美国大型企业运行着下一代防火墙。研究公司 IDC 评估防火墙和相关的统一威胁管理市场的营业额在 2015 是 76 亿美元，预计到 2020 年底将达到 127 亿美元。",-1)),t("p",null,[t("strong",null,[a[1]||(a[1]=e("如果你想升级，这里是《",-1)),l(r,{href:"https://www.networkworld.com/article/3236448/lan-wan/what-to-consider-when-deploying-a-next-generation-firewall.html"},{default:n(()=>[...a[0]||(a[0]=[e("当部署下一代防火墙时要考虑什么》",-1)])]),_:1})])]),a[20]||(a[20]=p('<h3 id="什么是防火墙-1" tabindex="-1">什么是防火墙？ <a class="header-anchor" href="#什么是防火墙-1" aria-label="Permalink to “什么是防火墙？”">​</a></h3><p>防火墙作为一个边界防御工具，其监控流量——要么允许它、要么屏蔽它。 多年来，防火墙的功能不断增强，现在大多数防火墙不仅可以阻止已知的一些威胁、执行高级访问控制列表策略，还可以深入检查流量中的每个数据包，并测试包以确定它们是否安全。大多数防火墙都部署为用于处理流量的网络硬件，和允许终端用户配置和管理系统的软件。越来越多的软件版防火墙部署到高度虚拟化的环境中，以在被隔离的网络或 IaaS 公有云中执行策略。</p><p>随着防火墙技术的进步，在过去十年中创造了新的防火墙部署选择，所以现在对于部署防火墙的最终用户来说，有了更多选择。这些选择包括：</p><h3 id="有状态的防火墙" tabindex="-1">有状态的防火墙 <a class="header-anchor" href="#有状态的防火墙" aria-label="Permalink to “有状态的防火墙”">​</a></h3><p>当防火墙首次创造出来时，它们是无状态的，这意味着流量所通过的硬件当单独地检查被监视的每个网络流量包时，屏蔽或允许是隔离的。从 1990 年代中后期开始，防火墙的第一个主要进展是引入了状态。有状态防火墙在更全面的上下文中检查流量，同时考虑到网络连接的工作状态和特性，以提供更全面的防火墙。例如，维持这个状态的防火墙可以允许某些流量访问某些用户，同时对其他用户阻塞同一流量。</p><h3 id="基于代理的防火墙" tabindex="-1">基于代理的防火墙 <a class="header-anchor" href="#基于代理的防火墙" aria-label="Permalink to “基于代理的防火墙”">​</a></h3><p>这些防火墙充当请求数据的最终用户和数据源之间的网关。在传递给最终用户之前，所有的流量都通过这个代理过滤。这通过掩饰信息的原始请求者的身份来保护客户端不受威胁。</p><h3 id="web-应用防火墙-waf" tabindex="-1">Web 应用防火墙（WAF） <a class="header-anchor" href="#web-应用防火墙-waf" aria-label="Permalink to “Web 应用防火墙（WAF）”">​</a></h3><p>这些防火墙位于特定应用的前面，而不是在更广阔的网络的入口或者出口上。基于代理的防火墙通常被认为是保护终端客户的，而 WAF 则被认为是保护应用服务器的。</p><h3 id="防火墙硬件" tabindex="-1">防火墙硬件 <a class="header-anchor" href="#防火墙硬件" aria-label="Permalink to “防火墙硬件”">​</a></h3><p>防火墙硬件通常是一个简单的服务器，它可以充当路由器来过滤流量和运行防火墙软件。这些设备放置在企业网络的边缘，位于路由器和 Internet 服务提供商（ISP）的连接点之间。通常企业可能在整个数据中心部署十几个物理防火墙。 用户需要根据用户基数的大小和 Internet 连接的速率来确定防火墙需要支持的吞吐量容量。</p><h3 id="防火墙软件" tabindex="-1">防火墙软件 <a class="header-anchor" href="#防火墙软件" aria-label="Permalink to “防火墙软件”">​</a></h3><p>通常，终端用户部署多个防火墙硬件端和一个中央防火墙软件系统来管理该部署。 这个中心系统是配置策略和特性的地方，在那里可以进行分析，并可以对威胁作出响应。</p><h3 id="下一代防火墙-ngfw" tabindex="-1">下一代防火墙（NGFW） <a class="header-anchor" href="#下一代防火墙-ngfw" aria-label="Permalink to “下一代防火墙（NGFW）”">​</a></h3><p>多年来，防火墙增加了多种新的特性，包括深度包检查、入侵检测和防御以及对加密流量的检查。下一代防火墙（NGFW）是指集成了许多先进的功能的防火墙。</p><h4 id="有状态的检测" tabindex="-1">有状态的检测 <a class="header-anchor" href="#有状态的检测" aria-label="Permalink to “有状态的检测”">​</a></h4><p>阻止已知不需要的流量，这是基本的防火墙功能。</p><h4 id="反病毒" tabindex="-1">反病毒 <a class="header-anchor" href="#反病毒" aria-label="Permalink to “反病毒”">​</a></h4><p>在网络流量中搜索已知病毒和漏洞，这个功能有助于防火墙接收最新威胁的更新，并不断更新以保护它们。</p><h4 id="入侵防御系统-ips" tabindex="-1">入侵防御系统（IPS） <a class="header-anchor" href="#入侵防御系统-ips" aria-label="Permalink to “入侵防御系统（IPS）”">​</a></h4><p>这类安全产品可以部署为一个独立的产品，但 IPS 功能正逐步融入 NGFW。 虽然基本的防火墙技术可以识别和阻止某些类型的网络流量，但 IPS 使用更细粒度的安全措施，如签名跟踪和异常检测，以防止不必要的威胁进入公司网络。 这一技术的以前版本是入侵检测系统（IDS），其重点是识别威胁而不是遏制它们，已经被 IPS 系统取代了。</p><h4 id="深度包检测-dpi" tabindex="-1">深度包检测（DPI） <a class="header-anchor" href="#深度包检测-dpi" aria-label="Permalink to “深度包检测（DPI）”">​</a></h4><p>DPI 可作为 IPS 的一部分或与其结合使用，但其仍然成为一个 NGFW 的重要特征，因为它提供细粒度分析流量的能力，可以具体到流量包头和流量数据。DPI 还可以用来监测出站流量，以确保敏感信息不会离开公司网络，这种技术称为数据丢失防御（DLP）。</p><h4 id="ssl-检测" tabindex="-1">SSL 检测 <a class="header-anchor" href="#ssl-检测" aria-label="Permalink to “SSL 检测”">​</a></h4><p>安全套接字层（SSL）检测是一个检测加密流量来测试威胁的方法。随着越来越多的流量进行加密，SSL 检测成为 NGFW 正在实施的 DPI 技术的一个重要组成部分。SSL 检测作为一个缓冲区，它在送到最终目的地之前解码流量以检测它。</p><h4 id="沙盒" tabindex="-1">沙盒 <a class="header-anchor" href="#沙盒" aria-label="Permalink to “沙盒”">​</a></h4><p>这个是被卷入 NGFW 中的一个较新的特性，它指防火墙接收某些未知的流量或者代码，并在一个测试环境运行，以确定它是否存在问题的能力。</p><hr>',28)),t("p",null,[a[3]||(a[3]=e("via: ",-1)),l(r,{href:"https://www.networkworld.com/article/3230457/lan-wan/what-is-a-firewall-perimeter-stateful-inspection-next-generation.html"},{default:n(()=>[...a[2]||(a[2]=[e("https://www.networkworld.com/article/3230457/lan-wan/what-is-a-firewall-perimeter-stateful-inspection-next-generation.html",-1)])]),_:1})]),t("p",null,[a[7]||(a[7]=e("作者：",-1)),l(r,{href:"https://www.networkworld.com/author/Brandon-Butler/"},{default:n(()=>[...a[4]||(a[4]=[e("Brandon Butler",-1)])]),_:1}),a[8]||(a[8]=e(" 译者：",-1)),l(r,{href:"https://github.com/zjon"},{default:n(()=>[...a[5]||(a[5]=[e("zjon",-1)])]),_:1}),a[9]||(a[9]=e(" 校对：",-1)),l(r,{href:"https://github.com/wxy"},{default:n(()=>[...a[6]||(a[6]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=e("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原创编译，",-1)),l(r,{href:"https://linux.cn/"},{default:n(()=>[...a[11]||(a[11]=[e("Linux中国",-1)])]),_:1}),a[14]||(a[14]=e(" 荣誉推出",-1))])])}const T=i(h,[["render",f]]);export{k as __pageData,T as default};
